//! Compare retained group composition and supplied wrap controls to native rows.
use spore_core::creature_skin_export_indices_v1::{adjust,project};
use std::{env,fs,io::{self,Write}};
fn word(b:&[u8],i:usize)->u32{u32::from_le_bytes(b[i*4..i*4+4].try_into().unwrap())}
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),3);let b=fs::read(&a[1]).unwrap();let t=fs::read(&a[2]).unwrap();assert_eq!((b.len(),t.len()),(4064,12384));let cases:Vec<_>=b.chunks_exact(8).map(|x|(word(x,0),word(x,1))).collect();let mut groups=Vec::new();let mut counts=Vec::new();let mut offset=0;for i in 0..8{let row=&t[i*387*4..(i+1)*387*4];let n=word(row,1) as usize;let c=word(row,2);let end=offset+3*n;groups.push(cases[offset..end].iter().map(|x|x.0).collect::<Vec<_>>());counts.push(c);offset=end;}assert_eq!(offset,252);let refs:Vec<_>=groups.iter().map(Vec::as_slice).collect();let mut output=Vec::new();for (j,start) in [0,0xfffffff0].into_iter().enumerate(){let v=project(&refs,&counts,start).unwrap();for (k,&value) in v.iter().enumerate(){assert_eq!(value,adjust(cases[j*252+k].0,cases[j*252+k].1));output.extend(value.to_le_bytes());}}for &(local,base) in &cases[504..]{output.extend(adjust(local,base).to_le_bytes());}io::stdout().write_all(&output).unwrap();}
